/* prog26_wildcard_match – reconstructed from the obfuscated binary
 *
 * The original program implements a classic wildcard matcher that
 * understands the two wild‑cards:
 *   *  – matches any (possibly empty) sequence of characters
 *   ?  – matches exactly one arbitrary character
 *
 * Behaviour:
 *   prog26_wildcard_match <pattern> <text>
 *
 *   * If the number of arguments is wrong, or either string is longer
 *     than 64 characters, the program prints "USAGE".
 *   * Otherwise it prints "MATCH" if the pattern matches the text,
 *     or "NO_MATCH" otherwise.
 *
 * The implementation below follows exactly the logic discovered in the
 * disassembly, using a DP table of size (65 × 65) – the same layout the
 * original binary used.
 */

#include <stdio.h>
#include <string.h>

#define MAXLEN 64          /* original program accepts strings up to 64 chars */

int main(int argc, char **argv)
{
    /* -----------------------------------------------------------------
       Argument validation – the original binary prints "USAGE" for any
       problem (wrong number of arguments or strings that are too long).
       ----------------------------------------------------------------- */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *pattern = argv[1];
    const char *text    = argv[2];

    size_t plen = strlen(pattern);
    size_t tlen = strlen(text);

    /* The binary allows lengths strictly less than 0x41 (65), i.e. up to 64. */
    if (plen > MAXLEN || tlen > MAXLEN) {
        puts("USAGE");
        return 0;
    }

    /* -----------------------------------------------------------------
       DP table – the original uses a static 2‑dimensional array of
       4‑byte integers.  We allocate the same (65 × 65) table.
       ----------------------------------------------------------------- */
    int dp[MAXLEN + 1][MAXLEN + 1] = {0};

    dp[0][0] = 1;                     /* empty pattern matches empty text */

    /* Initialise first column: pattern vs empty text */
    for (size_t i = 1; i <= plen; ++i) {
        if (pattern[i - 1] == '*')
            dp[i][0] = dp[i - 1][0];   /* '*' can match the empty string */
        else
            dp[i][0] = 0;
    }

    /* Fill the rest of the table */
    for (size_t i = 1; i <= plen; ++i) {
        for (size_t j = 1; j <= tlen; ++j) {
            char pc = pattern[i - 1];
            char tc = text[j - 1];

            if (pc == '*')
                dp[i][j] = dp[i - 1][j] || dp[i][j - 1];
            else if (pc == '?' || pc == tc)
                dp[i][j] = dp[i - 1][j - 1];
            else
                dp[i][j] = 0;
        }
    }

    puts(dp[plen][tlen] ? "MATCH" : "NO_MATCH");
    return 0;
}
